package com.ChaTop.Backend.Dto;import com.ChaTop.Backend.Models.User;public class RentalDto {    private int id;    private String name;    private int surface;    private double price;    private String picture;    private String description;    private User owner;    public int getId() {        return id;    }    public void setId(int id) {        this.id = id;    }    public String getName() {        return name;    }    public void setName(String name) {        this.name = name;    }    public int getSurface() {        return surface;    }    public void setSurface(int surface) {        this.surface = surface;    }    public double getPrice() {        return price;    }    public void setPrice(double price) {        this.price = price;    }    public String getPicture() {        return picture;    }    public void setPicture(String picture) {        this.picture = picture;    }    public String getDescription() {        return description;    }    public void setDescription(String description) {        this.description = description;    }    public User getOwner() {        return owner;    }    public void setOwner(User owner) {        this.owner = owner;    }}